/**
 * Closes the connection to the server
 *
 * @param {boolean} [immediately] - Close the socket without waiting for
 *   unsent data.
 */
close(immediately) {
  if (this.socket && this.socket.readyState === "open") {
    if (immediately) {
      this.logger.debug(
        `Closing connection to ${this._server.hostname} immediately!`
      );
      this.socket.closeImmediately();
    } else {
      this.logger.debug(`Closing connection to ${this._server.hostname}...`);
      this.socket.close();
    }
  } else {
    this.logger.debug(`Connection to ${this._server.hostname} closed`);
    this._free();
  }
}

/**
 * Stop the timer that closes the connection when the server does not close
 * it after QUIT.
 */
_clearQuitCloseTimer() {
  if (this._quitCloseTimer) {
    clearTimeout(this._quitCloseTimer);
    this._quitCloseTimer = null;
  }
}
